PREFIX : <http://www.semanticweb.org/energy-forecasting#>
SELECT ?substation ?ratio ?dispatcher WHERE {
  ?s a :Substation ; :currentLoad ?l ; :nominalCapacity ?c .
  FILTER (?l >= 0.85 * ?c)
  OPTIONAL { ?s :managedByDispatcher ?d . BIND (STRAFTER(STR(?d), "#") AS ?dispatcher) }
  BIND (?l / ?c AS ?ratio)
  BIND (STRAFTER(STR(?s), "#") AS ?substation)
} ORDER BY ?substation

PREFIX : <http://www.semanticweb.org/energy-forecasting#>
SELECT ?region (COUNT(?s) AS ?substations) (SUM(?c) AS ?capacity) (SUM(?l) AS ?load) WHERE {
  ?s a :Substation ; :region ?region ; :nominalCapacity ?c ; :currentLoad ?l .
} GROUP BY ?region ORDER BY ?region

PREFIX : <http://www.semanticweb.org/energy-forecasting#>
SELECT ?substation (COUNT(?c) AS ?consumers) WHERE {
  :Substation_1 :upstreamOf* ?s .
  OPTIONAL { ?c :connectedToSubstation ?s }
  BIND (STRAFTER(STR(?s), "#") AS ?substation)
} GROUP BY ?substation ORDER BY ?substation
